package com.ranjith.arena.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="interview_evaluations") public class InterviewEvaluation {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long sessionId; private int overallScore,technicalScore,communicationScore,projectScore,problemSolvingScore,relevanceScore,fillerWords,longPauses; private double averageResponseSeconds; @Lob @Column(columnDefinition="LONGTEXT") private String strengths; @Lob @Column(columnDefinition="LONGTEXT") private String improvements; @Lob @Column(columnDefinition="LONGTEXT") private String recommendation; private LocalDateTime createdAt=LocalDateTime.now();
 public Long getId(){return id;} public Long getSessionId(){return sessionId;} public void setSessionId(Long v){sessionId=v;} public int getOverallScore(){return overallScore;} public void setOverallScore(int v){overallScore=v;} public int getTechnicalScore(){return technicalScore;} public void setTechnicalScore(int v){technicalScore=v;} public int getCommunicationScore(){return communicationScore;} public void setCommunicationScore(int v){communicationScore=v;} public int getProjectScore(){return projectScore;} public void setProjectScore(int v){projectScore=v;} public int getProblemSolvingScore(){return problemSolvingScore;} public void setProblemSolvingScore(int v){problemSolvingScore=v;} public int getRelevanceScore(){return relevanceScore;} public void setRelevanceScore(int v){relevanceScore=v;} public int getFillerWords(){return fillerWords;} public void setFillerWords(int v){fillerWords=v;} public int getLongPauses(){return longPauses;} public void setLongPauses(int v){longPauses=v;} public double getAverageResponseSeconds(){return averageResponseSeconds;} public void setAverageResponseSeconds(double v){averageResponseSeconds=v;} public String getStrengths(){return strengths;} public void setStrengths(String v){strengths=v;} public String getImprovements(){return improvements;} public void setImprovements(String v){improvements=v;} public String getRecommendation(){return recommendation;} public void setRecommendation(String v){recommendation=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;}
}
